PudoResolveLocationPudoFragment.text:
query PudoResolveLocationPudoFragment(
    $id: String
    $includeAirportTerminals: Boolean = false
    $includeRAPUStatus: Boolean = false
    $includeTimezone: Boolean = false
    $source: EnumRVWebCommonLocationSource
    $provider: String
    $latitude: Float
    $longitude: Float
  ) {
    pudoResolveLocation(
      id: $id
      source: $source
      provider: $provider
      latitude: $latitude
      longitude: $longitude
    ) {
      ...PudoFragment

      timezone @include(if: $includeTimezone)

      airportTerminals @include(if: $includeAirportTerminals) {
        ...AirportTerminalsFragment
      }

      reserveAirportPickupData @include(if: $includeRAPUStatus) {
        ...ReserveAirportPickupData
      }
    }
  }
fragment PudoFragment on RVWebCommonPudoLocation {
    coordinate {
      latitude
