    }
    coordinateRefined {
      pickup {
        latitude
        longitude
      }
      dropoff {
        latitude
        longitude
      }
    }

    ...PudoFragmentBase
  }
fragment ReserveAirportPickupData on RVWebCommonReserveAirportPickupData {
