PudoResolveInitialParams.text:
query PudoResolveInitialParams(

    $includePickup: Boolean!
    $includeDrop0: Boolean!
    $includeDrop1: Boolean!
    $includeDrop2: Boolean!
    $includeDrop3: Boolean!
    $includeDrop4: Boolean!
    $includeFlight: Boolean!

    $pickupID: String
    $pickupProvider: String
    $pickupLatitude: Float
    $pickupLongitude: Float
    $pickupSource: EnumRVWebCommonLocationSource

    $drop0ID: String
    $drop0Provider: String
    $drop0Latitude: Float
    $drop0Longitude: Float
    $drop0Source: EnumRVWebCommonLocationSource

    $drop1ID: String
    $drop1Provider: String
    $drop1Latitude: Float
    $drop1Longitude: Float
    $drop1Source: EnumRVWebCommonLocationSource

    $drop2ID: String
    $drop2Provider: String
    $drop2Latitude: Float
    $drop2Longitude: Float
    $drop2Source: EnumRVWebCommonLocationSource

    $drop3ID: String
    $drop3Provider: String
    $drop3Latitude: Float
    $drop3Longitude: Float
    $drop3Source: EnumRVWebCommonLocationSource

    $drop4ID: String
    $drop4Provider: String
    $drop4Latitude: Float
    $drop4Longitude: Float
    $drop4Source: EnumRVWebCommonLocationSource

    $flightID: String!
  ) {
    pickup: pudoResolveLocation(
      id: $pickupID
      provider: $pickupProvider
      source: $pickupSource
      latitude: $pickupLatitude
      longitude: $pickupLongitude
    ) @include(if: $includePickup) {
      ...PudoFragment
      ...TimezoneAndAirportDataFragment
    }

    drop0: pudoResolveLocation(
      id: $drop0ID
      provider: $drop0Provider
      source: $drop0Source
      latitude: $drop0Latitude
      longitude: $drop0Longitude
    ) @include(if: $includeDrop0) {
      ...PudoFragment
      ...TimezoneAndAirportDataFragment
    }

    drop1: pudoResolveLocation(
      id: $drop1ID
      provider: $drop1Provider
      source: $drop1Source
      latitude: $drop1Latitude
      longitude: $drop1Longitude
    ) @include(if: $includeDrop1) {
      ...PudoFragment
      ...TimezoneAndAirportDataFragment
    }

    drop2: pudoResolveLocation(
      id: $drop2ID
      provider: $drop2Provider
      source: $drop2Source
      latitude: $drop2Latitude
      longitude: $drop2Longitude
    ) @include(if: $includeDrop2) {
      ...PudoFragment
      ...TimezoneAndAirportDataFragment
    }

    drop3: pudoResolveLocation(
      id: $drop3ID
      provider: $drop3Provider
      source: $drop3Source
      latitude: $drop3Latitude
      longitude: $drop3Longitude
    ) @include(if: $includeDrop3) {
      ...PudoFragment
      ...TimezoneAndAirportDataFragment
    }

    drop4: pudoResolveLocation(
      id: $drop4ID
      provider: $drop4Provider
      source: $drop4Source
      latitude: $drop4Latitude
      longitude: $drop4Longitude
    ) @include(if: $includeDrop4) {
      ...PudoFragment
      ...TimezoneAndAirportDataFragment
    }

    flight: pudoResolveFlight(id: $flightID) @include(if: $includeFlight) {
      ...PudoFlightFragment
    }
  }
