PudoLocationRefinement.text:
query PudoLocationRefinement(
    $pickup: InputRVWebCommonCoordinate!
    $pickupTime: Float
    $vvid: Int!
    $id: String
    $provider: String
    $source: EnumRVWebCommonLocationSource
  ) {
    pudoLocationRefinement(
      pickup: $pickup
      pickupTime: $pickupTime
      vvid: $vvid
      id: $id
      provider: $provider
      source: $source
    ) {
      anchor {
        ...PudoFragment
        locationRefinementMeta {
          instructions
          segment
        }
        timezone
      }
      containingZonePolygonPoints {
        latitude
        longitude
      }
      locations {
        ...RefinedLocationFragment
      }
      mode
    }
  }
fragment PudoFragment on RVWebCommonPudoLocation {
    coordinate {
      latitude
      longitude
    }
    coordinateRefined {
      pickup {
        latitude
        longitude
      }
      dropoff {
        latitude
        longitude
      }
    }

    ...PudoFragmentBase
  }
fragment RefinedLocationFragment on RVWebCommonRefinedLocation {
